eda.sys_Dialog.showConfirmationMessage(
  '即将删除选中的 3 个图元，是否继续？',
  '删除确认',   // 窗口标题
  '删除',       // 主按钮（确认）
  '取消',       // 次按钮（取消）
  (mainButtonClicked) => {
    if (mainButtonClicked) {
      console.log('用户点击了主按钮（删除）');
    } else {
      console.log('用户点击了次按钮（取消）');
    }
  }
);
